?><!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ニュース編集</title><style>body{font-family:system-ui;background:#f5fbf9;color:#174c47}.box{width:min(800px,92%);margin:30px auto;background:#fff;padding:24px;border-radius:16px}input,textarea{width:100%;padding:10px;margin:6px 0 14px;box-sizing:border-box;border:1px solid #cfe4de;border-radius:9px}textarea{min-height:360px}button{background:#1d8f7a;color:#fff;border:0;padding:11px 18px;border-radius:9px}.danger{background:#b44747}</style></head><body><main class="box"><p><a href="/dashboard.php">← 管理画面へ</a></p><h1>ニュース編集</h1><form method="post" action="/update-news.php"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf())?>"><input type="hidden" name="id" value="<?=$id?>"><input name="title" value="<?=htmlspecialchars($news['title'])?>" required><input name="slug" value="<?=htmlspecialchars($news['slug'])?>"><input name="category" value="<?=htmlspecialchars($news['category'])?>"><input name="excerpt" value="<?=htmlspecialchars($news['excerpt'])?>"><input name="cover_image_url" value="<?=htmlspecialchars($news['cover_image_url'])?>"><label><input type="checkbox" name="published" value="1" <?=$news['published']?'checked':''?>> 公開する</label><label>公開日時<input type="datetime-local" name="published_at" value="<?=htmlspecialchars($news['published_at']?date('Y-m-d\TH:i',strtotime($news['published_at'])):'')?>"></label><label>本文<div id="editor" contenteditable="true" style="min-height:360px;border:1px solid #cfe4de;border-radius:9px;padding:12px;background:#fff"><?= $news['content_html'] ?></div></label><input type="hidden" name="content_html" id="content_html"><div style="display:flex;gap:6px;flex-wrap:wrap"><button type="button" onclick="cmd('bold')">太字</button><button type="button" onclick="cmd('insertUnorderedList')">箇条書き</button><button type="button" onclick="cmd('formatBlock','<h2>')">見出し</button><button type="button" onclick="